export * as configs from './configs';
export * as environment from './environment';
export * as logger from './logger';
export * as typecast from './typecast';
export type * from './types';
export * as utils from './utils';
export * as validators from './validators';

import process from 'node:process';

const isCi = () => {
  return (
    process.env['ENV'] === 'ci' ||
    process.env['NODE_ENV'] === 'ci' ||
    process.env['CI'] === 'true' ||
    process.env['GITHUB_ACTIONS'] === 'true' ||
    process.env['GITLAB_CI'] === 'true'
  );
};

const isTest = () => {
  return (
    process.env['ENV'] === 'test' ||
    process.env['NODE_ENV'] === 'test' ||
    process.env['TEST'] === 'true' ||
    process.env['VITEST'] === 'true'
  );
};

const isLocal = () => {
  return (
    process.env['ENV'] === 'local' ||
    process.env['NODE_ENV'] === 'local' ||
    process.env['LOCAL'] === 'true'
  );
};

const isDevelopment = () => {
  return (
    process.env['ENV'] === 'development' ||
    process.env['NODE_ENV'] === 'development' ||
    process.env['DEVELOPMENT'] === 'true'
  );
};

const isStaging = () => {
  return (
    process.env['ENV'] === 'staging' ||
    process.env['NODE_ENV'] === 'staging' ||
    process.env['STAGING'] === 'true'
  );
};

const isProduction = () => {
  return (
    process.env['ENV'] === 'production' ||
    process.env['NODE_ENV'] === 'production' ||
    process.env['PRODUCTION'] === 'true'
  );
};

const isNonProduction = () => {
  return (
    (isCi() || isTest() || isLocal() || isDevelopment() || isStaging()) &&
    !isProduction()
  );
};

const isOtherEnvironment = (environment = '') => {
  let isOtherEnv =
    !(
      isCi() ||
      isTest() ||
      isLocal() ||
      isDevelopment() ||
      isStaging() ||
      isProduction()
    ) &&
    process.env['ENV'] !== undefined &&
    process.env['ENV'] !== '';

  if (
    !isOtherEnv &&
    environment &&
    typeof environment === 'string' &&
    environment.trim().length > 0
  ) {
    isOtherEnv = process.env['ENV'] === environment;
  }

    return isOtherEnv;
};

export {
  isCi,
  isDevelopment,
  isLocal,
  isNonProduction,
  isOtherEnvironment,
  isProduction,
  isStaging,
  isTest,
};

const createTypeGuard = <T extends Record<string, unknown>>(
  shape: Readonly<{ [K in keyof T]: (val: any) => boolean }>
): ((val: unknown) => val is T) => {
  return (val: any): val is T => {
    if (typeof val !== 'object' || val === null) {
      return false;
    }

    const obj: any = val;
    return Object.entries(shape).every((entry: any) => {
      const key = entry[0];
      const guard = entry[1];
      const property = obj[key];
      return guard(property);
    });
  };
};

const deepMerge = <T extends Record<string, unknown>>(...objects: readonly T[]): T => {
  const result: any = {};

  for (const obj of objects) {
    for (const key of Object.keys(obj)) {
      const val = obj[key];
      const resVal = result[key];

      if (
        val &&
        typeof val === 'object' &&
        resVal &&
        typeof resVal === 'object' &&
        !Array.isArray(val) &&
        !Array.isArray(resVal)
      ) {
        result[key] = deepMerge(
          resVal,
          val
        );
      } else {
        result[key] = val;
      }
    }
  }

  return result;
};

export { createTypeGuard, deepMerge };

import process from 'node:process';
import {
  accessSync,
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from 'node:fs';
import path from 'node:path';
import chalk from 'chalk';
import type { transport, Logger as WinstonLogger } from 'winston';
import { createLogger, format, transports } from 'winston';

import { isLocal } from '../environment';
import { serialize } from '../utils';

const { combine, json, metadata, printf, timestamp } = format;

// Removed unused logToFile
const rootDir = process.cwd();
const logDir = path.join(rootDir, 'tmp', 'logs');
const logFile = path.join(logDir, 'app.log');

// Setup function to create log directory and file
const setupLogDirectory = () => {
  // Use fs directly to avoid circular dependency
  if (!existsSync(logDir)) {
    mkdirSync(logDir, { recursive: true });
  }
  if (!existsSync(logFile)) {
    writeFileSync(logFile, '', { encoding: 'utf8' });
  }
};

class Logger {
  protected static instance: Logger;
  private readonly logFile: string;
  private readonly logger: WinstonLogger;
  private readonly logLevel: number;
  private readonly silent: boolean;

  constructor() {
    this.logFile = logFile;
    this.logLevel = process.env['LOG_LEVEL']
      ? Number.parseInt(process.env['LOG_LEVEL'], 10)
      : 1;

    if (process.env['DEBUG'] === 'true') {
      this.logLevel = 0;
    }

    this.silent = !isLocal;

    const transportsList: transport[] = [new transports.Console()];

    transportsList.push(new transports.File({ filename: this.logFile }));

    this.logger = createLogger({
      format: combine(
        timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
        metadata({ fillExcept: ['message', 'level', 'timestamp'] }),
        isLocal() ? customFormat : json()
      ),
      level: 'info',
      transports: transportsList,
    });
  }

  static getInstance(): Logger {
    Logger.instance = new Logger();
    return Logger.instance;
  }

  debug(message: string, ...args: readonly unknown[]): void {
    if (this.silent || this.logLevel > 0) {
      return;
    }

    this.logger.debug(chalk.gray(message), ...args);
  }

  error(message: string, ...args: readonly unknown[]): void {
    if (this.silent) {
      return;
    }

    this.logger.error(chalk.red(message), ...args);
  }

  info(message: string, ...args: readonly unknown[]): void {
    if (this.silent) {
      return;
    }

    this.logger.info(chalk.blue(message), ...args);
  }

  success(message: string, ...args: readonly unknown[]): void {
    if (this.silent && this.logLevel > 1) {
      return;
    }

    this.logger.info(chalk.green(message), ...args);
  }

  warn(message: string, ...args: readonly unknown[]): void {
    if (this.silent && this.logLevel > 2) {
      return;
    }

    this.logger.warn(chalk.yellow(message), ...args);
  }
}

class EventTargetLogger extends Logger {
  protected static override instance: EventTargetLogger;
  private readonly eventTarget: EventTarget;

  constructor() {
    super();
    this.eventTarget = new globalThis.EventTarget();
  }

  static override getInstance(): EventTargetLogger {
    EventTargetLogger.instance = new EventTargetLogger();
    return EventTargetLogger.instance;
  }

  override debug(message: string, ...args: readonly unknown[]): void {
    this.eventTarget.dispatchEvent(
      new globalThis.CustomEvent('log', { detail: { level: 'debug', message } })
    );
    super.debug(message, ...args);
  }

  override error(message: string, ...args: readonly unknown[]): void {
    this.eventTarget.dispatchEvent(
      new globalThis.CustomEvent('log', { detail: { level: 'error', message } })
    );
    super.error(message, ...args);
  }

  override info(message: string, ...args: readonly unknown[]): void {
    this.eventTarget.dispatchEvent(
      new globalThis.CustomEvent('log', { detail: { level: 'info', message } })
    );
    super.info(message, ...args);
  }

  override success(message: string, ...args: readonly unknown[]): void {
    this.eventTarget.dispatchEvent(
      new globalThis.CustomEvent('log', {
        detail: { level: 'info', message },
      })
    );
    super.success(message, ...args);
  }

  override warn(message: string, ...args: readonly unknown[]): void {
    this.eventTarget.dispatchEvent(
      new globalThis.CustomEvent('log', { detail: { level: 'warn', message } })
    );
    super.warn(message, ...args);
  }
}

const customFormat = printf((info: Readonly<Record<string, unknown>>) => {
  const level = String(info['level']);
  const message = String(info['message']);
  const meta: any = info['metadata'];
  const time = String(info['timestamp']);
  const outputTimestamp = chalk.white(time);
  const outputLevel = level.toUpperCase();
  let logMessage = `${outputTimestamp} [${outputLevel}]: ${message}`;
  if (meta && Object.keys(meta).length > 0) {
    logMessage += ` ${chalk.gray(JSON.stringify(serialize.safeSerialize(meta)))}`;
  }
  return logMessage;
});

const readLogs = (limit = 100): string => {
  const targetLogDir = path.join(rootDir, 'tmp', 'logs');
  const targetLogFile = path.join(targetLogDir, 'app.log');

  try {
    accessSync(targetLogFile);
    const content = readFileSync(targetLogFile, 'utf8');

    if (!content.trim()) {
      return 'No logs available yet';
    }

    const lines = content.split('\n').filter(Boolean);
    return lines.slice(-limit).join('\n');
  } catch {
    return 'No logs available yet';
  }
};

const logger = Logger.getInstance();
const eventTargetLogger = EventTargetLogger.getInstance();

export {
  customFormat,
  EventTargetLogger,
  eventTargetLogger,
  Logger,
  logger,
  readLogs,
  setupLogDirectory,
};

