import process from 'node:process';

const apiBaseUrl = process.env['API_URL'] || 'http://localhost:3000';
const siteUrl = process.env['SITE_URL'] || 'http://localhost:3001';

const healthCheckEndpoint = '/';
const healthCheckUrl = `${apiBaseUrl}${healthCheckEndpoint}`;

const apiEndpoint = '/api';
const apiUrl = `${apiBaseUrl}${apiEndpoint}`;

const docsEndpoint = '/docs';
const docsUrl = `${apiBaseUrl}${docsEndpoint}`;

const apiDocsEndpoint = '/api-docs';
const apiDocsUrl = `${apiBaseUrl}${apiDocsEndpoint}`;

const trpcEndpoint = '/trpc';
const trpcUrl = `${apiBaseUrl}${trpcEndpoint}`;

const trpcDocsEndpoint = '/trpc-docs';
const trpcDocsUrl = `${apiBaseUrl}${trpcDocsEndpoint}`;

const trpcPlaygroundEndpoint = '/trpc-playground';
const trpcPlaygroundUrl = `${apiBaseUrl}${trpcPlaygroundEndpoint}`;

const requestTypes = {
  http: 'HTTP',
  trpc: 'tRPC',
} as const;

type RequestType = (typeof requestTypes)[keyof typeof requestTypes];

const isTrpcEndpoint = (url: string): boolean => {
  return (
    (url.startsWith(trpcEndpoint) &&
      !url.startsWith(trpcPlaygroundEndpoint) &&
      !url.startsWith(trpcDocsEndpoint)) ||
    (url.startsWith(trpcUrl) &&
      !url.startsWith(trpcPlaygroundUrl) &&
      !url.startsWith(trpcDocsUrl))
  );
};

const getRequestType = (url: string): RequestType => {
  if (isTrpcEndpoint(url)) {
    return requestTypes.trpc;
  }
  return requestTypes.http;
};

const isTrpcRequest = (requestType: RequestType): boolean => {
  if (requestType === requestTypes.trpc) {
    return true;
  }
  return false;
};

export {
  apiBaseUrl,
  apiDocsEndpoint,
  apiDocsUrl,
  apiEndpoint,
  apiUrl,
  docsEndpoint,
  docsUrl,
  getRequestType,
  healthCheckEndpoint,
  healthCheckUrl,
  isTrpcEndpoint,
  isTrpcRequest,
  requestTypes,
  siteUrl,
  trpcDocsEndpoint,
  trpcDocsUrl,
  trpcEndpoint,
  trpcPlaygroundEndpoint,
  trpcPlaygroundUrl,
  trpcUrl,
};

export type { RequestType };

/**
 * Shared parameter type definitions used by both runtime (invoker) and build-time (autogen)
 * This ensures consistency between how we extract parameters at runtime vs how we document them
 */

/**
 * Basic parameter information - used by runtime invoker
 * Lightweight, contains only what's needed for function invocation
 */
export interface ParameterInfo {
  /** Parameter name extracted from function signature */
  readonly name: string;
}

/**
 * Extended parameter metadata - used by build-time autogen
 * Includes TypeScript type information, JSDoc, and other documentation details
 */
export interface ParameterMetadata extends ParameterInfo {
  /** Default value if parameter is optional */
  readonly defaultValue?:
    | boolean
    | number
    | string
    | undefined
    | readonly unknown[];

  /** JSDoc description extracted from @param tag */
  readonly description?: string | undefined;

  /** For object parameters, nested property metadata */
  readonly properties?: readonly ParameterMetadata[] | undefined;

  /** Whether the parameter is required (not optional) */
  readonly required: boolean;

  /** TypeScript type as string (e.g., "string", "number", "UserProfile") */
  readonly type: string;
}

import process from 'node:process';
import { logger } from '../logger';

const checks = (
    checksArr: any
): { message?: string; valid: boolean } => {
  let valid = true;
  let message = 'All checks passed';
  for (const check of checksArr) {
    // Force a boolean conversion
    const result = Boolean(
      typeof check.property === 'function' ? check.property() : check.property
    );
    if (result) {
      valid = false;
      message = check.message || 'Check failed';
      if (check.error instanceof Error) {
        throw check.error;
      }
      break;
    }
  }
  return { message, valid };
};

const exit = ({
  code = 1,
  message = '',
}: Readonly<{
  code?: number;
  message?: string;
}>) => {
  if (message) {
    logger.error(message);
  }
  process.exit(code);
};

export { checks, exit };

import process from 'node:process';
import chalk, { type ChalkInstance, type ColorSupportLevel } from 'chalk';

import { getRandomText } from './text';

const DEFAULT_CHALK_LEVEL = 3 as ColorSupportLevel;

const isColorSupportLevel = (level: number): level is ColorSupportLevel =>
  [0, 1, 2, 3].includes(level);

const getChalkLevel = (): ColorSupportLevel => {
  const envLevel = process.env['CHALK_LEVEL'];
  if (envLevel) {
    const parsed = Number.parseInt(envLevel, 10);
    if (isColorSupportLevel(parsed)) {
      return parsed;
    }
  }
  return DEFAULT_CHALK_LEVEL;
};

chalk.level = getChalkLevel();

const colors = [
  chalk.red,
  chalk.green,
  chalk.blue,
  chalk.yellow,
  chalk.cyan,
  chalk.magenta,
];

const readonlyColors: readonly ChalkInstance[] = colors;

// biome-ignore lint/suspicious/noControlCharactersInRegex: ignore
const ANSI_ESCAPE_CODE_REGEX = new RegExp(`^(${String.fromCharCode(27)}\\[[0-9;]*m)`);

const defaultColor = chalk.white;
const resetColor = chalk.reset;
const resetColorAnsiEscapeCode = '\u001B[39m';

const getRandomColor = (id = '') => {
  let colorId = id;
  if (!colorId) {
    colorId = getRandomText();
  } else if (colorId === 'no-id') {
    return chalk.white;
  }

  const index =
    colorId.split('').reduce((acc, char) => acc + (char.codePointAt(0) ?? 0), 0) %
    colors.length;

  return colors[index];
};

const getNextRandomColor = (
  id: string,
  previousColor: any
) => {
  let colorId = id;
  if (!colorId) {
    colorId = getRandomText();
  }

  const nextColor = getRandomColor(colorId);

  if (
    !previousColor ||
    nextColor.level !== previousColor.level
  ) {
    return { nextColor, previousColor };
  }

  const previousColorIndex = readonlyColors.indexOf(previousColor);

  const nextColorIndex = (previousColorIndex + 1) % colors.length;

  return { nextColor: colors[nextColorIndex], previousColor };
};

const getAnsiEscapeCodes = (colorFunction: (text: string) => string) => {
  const testString = getRandomText();
  const coloredString = colorFunction(testString);

  const escapeCodeMatch = coloredString.match(ANSI_ESCAPE_CODE_REGEX);

  if (escapeCodeMatch) {
    return {
      close: resetColorAnsiEscapeCode,
      open: escapeCodeMatch[0],
    };
  }

  return { close: '', open: '' };
};

export {
  colors,
  defaultColor,
  getAnsiEscapeCodes,
  getNextRandomColor,
  getRandomColor,
  resetColor,
  resetColorAnsiEscapeCode,
};

const formatTimestamp = (timestamp: number) => {
  const date = new Date(timestamp);
  return date.toISOString();
};

const convertToLocalDate = (timestamp: number) => {
  const date = new Date(timestamp);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours24 = date.getHours();
  const minutes = String(date.getMinutes()).padStart(2, '0');
  const seconds = String(date.getSeconds()).padStart(2, '0');
  const milliseconds = String(date.getMilliseconds()).padStart(
    MILLISECONDS_PADDING_DIGITS,
    '0'
  );
  const ampm = hours24 >= NOON_HOUR ? 'PM' : 'AM';
  const hours12 = hours24 % NOON_HOUR || NOON_HOUR;

  return `${year}-${month}-${day} ${String(hours12).padStart(
    2,
    '0'
  )}:${minutes}:${seconds}.${milliseconds} ${ampm}`;
};

const MILLISECONDS_PER_SECOND = 1000;
const SECONDS_PER_MINUTE = 60;
const MINUTES_PER_HOUR = 60;
const HOURS_PER_DAY = 24;
const NOON_HOUR = 12;
const MILLISECONDS_PADDING_DIGITS = 3;

const formatDuration = (milliseconds: number): string => {
  const seconds = Math.floor(milliseconds / MILLISECONDS_PER_SECOND);
  const minutes = Math.floor(seconds / SECONDS_PER_MINUTE);
  const hours = Math.floor(minutes / MINUTES_PER_HOUR);
  const days = Math.floor(hours / HOURS_PER_DAY);

  const remainingHours = hours % HOURS_PER_DAY;
  const remainingMinutes = minutes % SECONDS_PER_MINUTE;
  const remainingSeconds = seconds % SECONDS_PER_MINUTE;
  const remainingMilliseconds = milliseconds % MILLISECONDS_PER_SECOND;

  const parts: string[] = [];

  if (days > 0) {
    parts.push(`${days}d`);
  }
  if (remainingHours > 0) {
    parts.push(`${remainingHours}h`);
  }
  if (remainingMinutes > 0) {
    parts.push(`${remainingMinutes}m`);
  }
  if (remainingSeconds > 0) {
    parts.push(`${remainingSeconds}s`);
  }
  if (remainingMilliseconds > 0) {
    parts.push(`${remainingMilliseconds}ms`);
  }

  return parts.join(' ');
};

export { convertToLocalDate, formatDuration, formatTimestamp };

import process from 'node:process';
