      case '[': {
        inSquareBrackets++;
        break;
      }
      case ']': {
        inSquareBrackets--;
        break;
      }
      case '{': {
        inCurlyBrackets++;
        break;
      }
      case '}': {
        inCurlyBrackets--;
        break;
      }
      default: {
