const PARAM_TAG_REGEX = /@param\s+(?:\{[^}]+\}\s+)?(\w+)\s+(.+)/;

/**
 * Extracts metadata for all parameters of a service method.
 * Uses both runtime invocation (via invoker.ts) and AST analysis (ts-morph)
 * 
 * @param methodDecl - The ts-morph MethodDeclaration node
 * @param serviceFilePath - Absolute path to the service file
 * @param serviceClassName - Name of the service class
