/**
 * Reduces waiting time by two blocks (about 6 seconds)
 */
const reduceWaitingTimeByTwoBlocks = (waitingTime: number): number => {
  const reducedTime = Math.max(
    waitingTime - TWO_BLOCKS_MS,
